import {eventPayload} from './admin-event-form.js';
export function mountEventEditor(root,client,event,onSaved){
 const panel=document.createElement('details');panel.className='panel';panel.innerHTML='<summary>แก้ไขข้อมูลกิจกรรม</summary><form><label>ชื่อกิจกรรม<input name="name" required maxlength="2000"></label><label>วันและเวลา<input name="date" required maxlength="2000"></label><label>สถานที่<input name="place" required maxlength="2000"></label><label>รายละเอียด<textarea name="description" required maxlength="2000" rows="4"></textarea></label><label>จำนวนรับ<input name="capacity" type="number" min="1" max="100000" required></label><p class="sub">การแก้ไขไม่เปลี่ยนข้อมูลที่เก็บไว้ในใบสมัครเดิม</p><button class="primary" type="submit">บันทึกการแก้ไข</button><p role="status"></p></form>';root.append(panel);const form=panel.querySelector('form');for(const key of ['name','date','place','description','capacity'])form.elements[key].value=event[key]??'';
 let busy=false,expected=Object.fromEntries(['name','date','place','description','capacity'].map(key=>[key,event[key]??'']));
 form.onsubmit=async e=>{e.preventDefault();if(busy||!panel.isConnected)return;busy=true;const button=form.querySelector('button'),status=form.querySelector('[role=status]');button.disabled=true;try{const payload=eventPayload(form);await client.operate({action:'editEvent',eventId:event.id,event:payload,expected});if(!panel.isConnected)return;expected={...payload};status.textContent='บันทึกแล้ว';if(onSaved)await onSaved()}catch(error){if(panel.isConnected)status.textContent=error.message||'บันทึกไม่ได้ กดลองใหม่'}finally{busy=false;if(panel.isConnected)button.disabled=false}};
}
